import { auth } from "@/lib/auth"
import { prisma } from "@/db/prisma"
import Link from "next/link"
import { Card, CardContent } from "@/components/ui/card"
import { Badge } from "@/components/ui/badge"
import { Input } from "@/components/ui/input"
import { Button } from "@/components/ui/button"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import {
  Clock,
  FileText,
  ListOrdered,
  AlignLeft,
  BookOpen,
  ImageIcon,
  ImagePlus,
  HistoryIcon,
  ExternalLink,
  RefreshCw,
  SearchX,
} from "lucide-react"

const contentTypeConfig: Record<
  string,
  { label: string; icon: typeof FileText; color: string }
> = {
  title: {
    label: "商品标题",
    icon: FileText,
    color: "bg-blue-100 text-blue-700 dark:bg-blue-900/40 dark:text-blue-300",
  },
  bulletPoints: {
    label: "要点描述",
    icon: ListOrdered,
    color:
      "bg-emerald-100 text-emerald-700 dark:bg-emerald-900/40 dark:text-emerald-300",
  },
  shortDesc: {
    label: "短描述",
    icon: AlignLeft,
    color:
      "bg-violet-100 text-violet-700 dark:bg-violet-900/40 dark:text-violet-300",
  },
  longDesc: {
    label: "长描述",
    icon: BookOpen,
    color:
      "bg-amber-100 text-amber-700 dark:bg-amber-900/40 dark:text-amber-300",
  },
  mainImage: {
    label: "商品主图",
    icon: ImageIcon,
    color: "bg-pink-100 text-pink-700 dark:bg-pink-900/40 dark:text-pink-300",
  },
  sceneImage: {
    label: "场景图",
    icon: ImagePlus,
    color: "bg-cyan-100 text-cyan-700 dark:bg-cyan-900/40 dark:text-cyan-300",
  },
}

const platformLabels: Record<string, string> = {
  amazon: "Amazon",
  shopify: "Shopify",
  tiktok: "TikTok Shop",
}

function formatDate(date: Date): string {
  const now = new Date()
  const diff = now.getTime() - date.getTime()
  const days = Math.floor(diff / (1000 * 60 * 60 * 24))

  if (days === 0) return "今天"
  if (days === 1) return "昨天"
  if (days < 7) return `${days}天前`
  return date.toLocaleDateString("zh-CN", {
    month: "short",
    day: "numeric",
    year: date.getFullYear() !== now.getFullYear() ? "numeric" : undefined,
  })
}

export default async function HistoryPage({
  searchParams,
}: {
  searchParams: Promise<{ q?: string; contentType?: string; platform?: string }>
}) {
  const session = await auth()
  if (!session?.user?.id) return null

  const { q, contentType, platform } = await searchParams
  const hasFilters = !!(q || contentType || platform)

  // Build where clause
  const projectFilter: { userId: string; productName?: { contains: string }; platform?: string } = {
    userId: session.user.id,
  }
  if (q) projectFilter.productName = { contains: q }
  if (platform) projectFilter.platform = platform

  const where: { project: typeof projectFilter; contentType?: string } = {
    project: projectFilter,
  }
  if (contentType) where.contentType = contentType

  const records = await prisma.generationRecord.findMany({
    where,
    orderBy: { createdAt: "desc" },
    include: {
      project: {
        select: {
          productName: true,
          platform: true,
          id: true,
        },
      },
    },
  })

  const allRecords = records.map((record) => ({
    ...record,
    projectName: record.project.productName,
    projectId: record.project.id,
    platform: record.project.platform,
  }))

  const totalCount = allRecords.length

  return (
    <div className="mx-auto max-w-4xl px-4 sm:px-6 lg:px-8 py-8">
      {/* Header */}
      <div className="mb-6">
        <h1 className="text-2xl font-bold tracking-tight">历史记录</h1>
        <p className="text-sm text-muted-foreground mt-1">
          {hasFilters
            ? `找到 ${totalCount} 条匹配的记录`
            : `共 ${totalCount} 条生成记录`}
        </p>
      </div>

      {/* Search & Filter */}
      <form className="flex flex-wrap items-end gap-3 mb-6">
        <div className="flex-1 min-w-[200px]">
          <Input
            name="q"
            placeholder="搜索项目名称..."
            defaultValue={q || ""}
            className="h-9"
          />
        </div>
        <Select name="contentType" defaultValue={contentType || ""}>
          <SelectTrigger className="h-9 w-[130px]">
            <SelectValue placeholder="内容类型" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="">全部类型</SelectItem>
            <SelectItem value="title">商品标题</SelectItem>
            <SelectItem value="bulletPoints">要点描述</SelectItem>
            <SelectItem value="shortDesc">短描述</SelectItem>
            <SelectItem value="longDesc">长描述</SelectItem>
            <SelectItem value="mainImage">商品主图</SelectItem>
            <SelectItem value="sceneImage">场景图</SelectItem>
          </SelectContent>
        </Select>
        <Select name="platform" defaultValue={platform || ""}>
          <SelectTrigger className="h-9 w-[130px]">
            <SelectValue placeholder="平台" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="">全部平台</SelectItem>
            <SelectItem value="amazon">Amazon</SelectItem>
            <SelectItem value="shopify">Shopify</SelectItem>
            <SelectItem value="tiktok">TikTok Shop</SelectItem>
          </SelectContent>
        </Select>
        <Button type="submit" size="sm" variant="secondary">
          筛选
        </Button>
        {hasFilters && (
          <Button size="sm" variant="ghost" render={<Link href="/history" />}>
            清除
          </Button>
        )}
      </form>

      {/* Records */}
      {allRecords.length === 0 ? (
        <Card className="py-12">
          <CardContent className="flex flex-col items-center justify-center text-center">
            {hasFilters ? (
              <>
                <SearchX className="size-10 text-muted-foreground/50 mb-4" />
                <p className="text-muted-foreground mb-1">没有找到匹配的记录</p>
                <p className="text-xs text-muted-foreground/60 mb-4">
                  试试调整搜索条件或筛选器
                </p>
                <Link
                  href="/history"
                  className="inline-flex items-center gap-1.5 rounded-lg bg-primary px-4 py-2 text-sm font-medium text-primary-foreground hover:bg-primary/90 transition-colors"
                >
                  清除筛选
                </Link>
              </>
            ) : (
              <>
                <HistoryIcon className="size-10 text-muted-foreground/50 mb-4" />
                <p className="text-muted-foreground mb-1">还没有生成记录</p>
                <p className="text-xs text-muted-foreground/60 mb-4">
                  创建一个项目并生成内容后，记录会出现在这里
                </p>
                <Link
                  href="/dashboard/new"
                  className="inline-flex items-center gap-1.5 rounded-lg bg-primary px-4 py-2 text-sm font-medium text-primary-foreground hover:bg-primary/90 transition-colors"
                >
                  新建项目
                </Link>
              </>
            )}
          </CardContent>
        </Card>
      ) : (
        <div className="space-y-3">
          {allRecords.map((record) => {
            const config = contentTypeConfig[record.contentType]
            const Icon = config?.icon || FileText
            const label = config?.label || record.contentType
            const colorClass =
              config?.color || "bg-muted text-muted-foreground"

            return (
              <Card key={record.id} className="transition-all duration-300 hover:shadow-md hover:border-primary/20">
                <CardContent className="py-4">
                  <div className="flex items-start gap-4">
                    {/* Type Icon */}
                    <div
                      className={`flex size-9 shrink-0 items-center justify-center rounded-lg ${colorClass}`}
                    >
                      <Icon className="size-4" />
                    </div>

                    {/* Content */}
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2 mb-1">
                        <Link
                          href={`/results?projectId=${record.projectId}`}
                          className="text-sm font-medium hover:text-primary transition-colors truncate"
                        >
                          {record.projectName}
                        </Link>
                        <Badge
                          variant="secondary"
                          className="shrink-0 text-[10px] px-1.5 py-0"
                        >
                          {label}
                        </Badge>
                        {record.platform && (
                          <span className="shrink-0 text-[10px] text-muted-foreground/60">
                            {platformLabels[record.platform] ||
                              record.platform}
                          </span>
                        )}
                      </div>

                      {record.content && (
                        <p className="text-xs text-muted-foreground line-clamp-2 leading-relaxed">
                          {record.content}
                        </p>
                      )}
                      {record.imageUrl && !record.content && (
                        <p className="text-xs text-muted-foreground truncate">
                          🖼️ {record.imageUrl}
                        </p>
                      )}

                      <div className="flex items-center gap-3 mt-2">
                        <span className="flex items-center gap-1 text-[11px] text-muted-foreground/60">
                          <Clock className="size-3" />
                          {formatDate(new Date(record.createdAt))}
                        </span>
                        <Link
                          href={`/results?projectId=${record.projectId}`}
                          className="flex items-center gap-1 text-[11px] text-primary/70 hover:text-primary transition-colors"
                        >
                          <ExternalLink className="size-3" />
                          查看详情
                        </Link>
                        <Link
                          href={`/dashboard/new?reuseProjectId=${record.projectId}`}
                          className="flex items-center gap-1 text-[11px] text-primary/70 hover:text-primary transition-colors"
                        >
                          <RefreshCw className="size-3" />
                          再次使用
                        </Link>
                      </div>
                    </div>
                  </div>
                </CardContent>
              </Card>
            )
          })}
        </div>
      )}
    </div>
  )
}
